//==========================
// Featured carousel (RingList)
//==========================
//--- doFeatured -----------------------------------------------------------------------------------
// What    : The Featured carousel: the best rated games in a circular doubly linked list. n goes to
//           the next game and p to the previous one, and the list wraps around at both ends.
// Used by : doDiscover
//--------------------------------------------------------------------------------------------------
void doFeatured(Store& st) {
    std::vector<const GameNode*> list = collectGames(st.games, std::vector<std::string>());
    if (list.empty()) { std::cout << "  (no games yet)\n"; return; }
    SortStats stats;
    std::vector<const GameNode*> best = list;
    mergeSort(best.data(), (int)best.size(),
              [&st](const GameNode* a, const GameNode* b) { return goesBefore(a, b, SORT_RATING, st.reviews); }, &stats);

    RingList<int> ring;                                    // game ids, best rated first
    for (size_t i = 0; i < best.size() && i < 8; i++) ring.pushBack(best[i]->gameId);

    while (true) {
        int id = 0;
        ring.current(id);
        GameNode* g = findGameById(st.games, id);
        tuiSection("FEATURED GAMES");
        std::cout << " " << ring.position() << " of " << ring.size() << "  (the list is a circle: next after the last is the first)\n";
        if (g != nullptr) showGamePage(st, g);
        std::cout << " n = next   p = previous   0 = back\n";
        std::string in;
        if (!readLine("Choice: ", in)) return;
        in = gameTrim(in);
        if (in == "0" || in.empty()) return;
        if (in == "n") ring.moveNext();
        else if (in == "p") ring.movePrev();
        else std::cout << "  Invalid choice.\n";
    }
}

//==========================
// Browse by genre (general tree)
//==========================
// fills gameCount of every genre with the number of games that carry that tag
//--- countGenreGames ------------------------------------------------------------------------------
// What    : Fills the game count of every genre node from the tag index of the catalog.
// Used by : doGenres
//--------------------------------------------------------------------------------------------------
void countGenreGames(const Store& st, GenreNode* node) {
    if (node == nullptr) return;
    std::map<std::string, int> index = buildTagIndex(st.games);
    std::vector<GenreVisit> all;
    genrePreorder(node, 0, all);
    for (size_t i = 0; i < all.size(); i++) {
        std::map<std::string, int>::const_iterator it = index.find(all[i].node->name);
        all[i].node->gameCount = (it == index.end()) ? 0 : it->second;
    }
}

//--- doGenres -------------------------------------------------------------------------------------
// What    : Browse by genre: prints the genre tree with counts, shows the games of a branch, and
//           prints the preorder, postorder and level order traversals.
// Used by : doDiscover
//--------------------------------------------------------------------------------------------------
void doGenres(Store& st) {
    GenreNode* root = genreBuildDefault();
    countGenreGames(st, root);
    while (true) {
        tuiSection("BROWSE BY GENRE");
        std::vector<GenreVisit> order;
        genrePreorder(root, 0, order);
        for (size_t i = 0; i < order.size(); i++) {
            if (order[i].depth == 0) continue;
            std::cout << "  " << std::string((size_t)(order[i].depth - 1) * 3, ' ') << order[i].node->name
                      << "  (" << order[i].node->gameCount << ", " << genreTotal(order[i].node) << " with subgenres)\n";
        }
        std::cout << "\n The tree has " << genreCount(root) << " genres and a height of " << genreHeight(root) << ".\n"
                  << " 1. Show the games of a genre (and its subgenres)\n"
                  << " 2. Show the traversals (preorder / postorder / level order)\n 0. Back\n";
        int c = readInt("Choice: ");
        if (c == -2 || c == 0) break;
        if (c == 1) {
            std::string name;
            if (!readLine("Genre name: ", name)) break;
            name = gameToLower(gameTrim(name));
            GenreNode* found = genreFind(root, name);
            if (found == nullptr) { std::cout << "  No such genre.\n"; continue; }
            std::vector<std::string> names;
            genreNamesUnder(found, names);
            std::vector<const GameNode*> list;
            for (GameNode* g = st.games.head; g != nullptr; g = g->next) {
                std::vector<std::string> own = splitTags(g->tags);
                bool match = (name == "all games");
                for (size_t a = 0; a < own.size() && !match; a++) {
                    for (size_t b = 0; b < names.size(); b++) if (own[a] == names[b]) { match = true; break; }
                }
                if (match) list.push_back(g);
            }
            if (list.empty()) { std::cout << "  No games in that genre yet.\n"; continue; }
            insertionSortGames(list, st.sortKey, st.reviews);
            std::vector<std::string> path;
            genrePath(root, name, path);
            std::string where;
            for (size_t i = 0; i < path.size(); i++) where += (i ? " > " : "") + path[i];
            tuiSection(where);
            printGameTable(st, list);
        } else if (c == 2) {
            std::vector<GenreVisit> pre, post, level;
            genrePreorder(root, 0, pre);
            genrePostorder(root, 0, post);
            genreLevelOrder(root, level);
            const char* titles[3] = {"Preorder (parent first)", "Postorder (children first)", "Level order (row by row, uses a queue)"};
            std::vector<GenreVisit>* sets[3] = {&pre, &post, &level};
            for (int t = 0; t < 3; t++) {
                std::cout << "\n " << titles[t] << ":\n  ";
                for (size_t i = 0; i < sets[t]->size(); i++) std::cout << (i ? ", " : "") << (*sets[t])[i].node->name;
                std::cout << "\n";
            }
        } else {
            std::cout << "  Invalid choice.\n";
        }
    }
    genreFree(root);
}

//==========================
// Recently viewed and Back / Forward
//==========================
//--- doRecent -------------------------------------------------------------------------------------
// What    : Prints the recently viewed games, newest first.
// Used by : doDiscover
//--------------------------------------------------------------------------------------------------
void doRecent(Store& st) {
    tuiSection("RECENTLY VIEWED");
    std::vector<int> ids = st.recent.newestFirst();
    if (ids.empty()) { std::cout << "  (nothing yet, open a game page first)\n"; return; }
    for (size_t i = 0; i < ids.size(); i++) {
        GameNode* g = findGameById(st.games, ids[i]);
        if (g != nullptr) std::cout << "  " << (i + 1) << ". [" << g->gameId << "] " << g->title << "\n";
    }
}

//--- doHistory ------------------------------------------------------------------------------------
// What    : Back / Forward between the game pages that were opened, like a web browser (two
//           stacks).
// Used by : doDiscover
//--------------------------------------------------------------------------------------------------
void doHistory(Store& st) {
    while (true) {
        tuiSection("PAGE HISTORY (Back / Forward)");
        GameNode* cur = findGameById(st.games, st.history.current());
        if (cur == nullptr) { std::cout << "  (no page opened yet)\n"; return; }
        showGamePage(st, cur);
        std::cout << " b = back" << (st.history.canGoBack() ? "" : " (nothing behind)")
                  << "   f = forward" << (st.history.canGoForward() ? "" : " (nothing ahead)") << "   0 = leave\n";
        std::string in;
        if (!readLine("Choice: ", in)) return;
        in = gameTrim(in);
        if (in == "0" || in.empty()) return;
        if (in == "b") { if (st.history.goBack() == 0) std::cout << "  Nothing behind.\n"; }
        else if (in == "f") { if (st.history.goForward() == 0) std::cout << "  Nothing ahead.\n"; }
        else std::cout << "  Invalid choice.\n";
    }
}

//==========================
// Downloads (queue + worker thread)
//==========================
//--- doDownloads ----------------------------------------------------------------------------------
// What    : The Downloads screen: install a game from the library (queue + worker thread), watch
//           the progress bar, uninstall. Installed games are remembered for the session.
// Used by : runAction (store.h)
//--------------------------------------------------------------------------------------------------
void doDownloads(Store& st) {
    while (true) {
        std::vector<int> done = st.downloads->takeFinished();
        for (size_t i = 0; i < done.size(); i++) st.installed.insert(done[i]);

        tuiSection("DOWNLOADS");
        int active = st.downloads->activeId();
        if (active != 0) {
            GameNode* g = findGameById(st.games, active);
            int p = st.downloads->activeProgress();
            std::cout << " Installing: " << (g ? g->title : std::string("?")) << "  " << progressBar(p, 100, 30) << " " << p << "%\n";
        } else {
            std::cout << " No download is running.\n";
        }
        std::vector<int> waiting = st.downloads->waitingList();
        for (size_t i = 0; i < waiting.size(); i++) {
            GameNode* g = findGameById(st.games, waiting[i]);
            std::cout << "   waiting " << (i + 1) << ": " << (g ? g->title : std::string("?")) << "\n";
        }
        std::cout << "\n Installed games:\n";
        bool any = false;
        for (OwnedNode* o = st.current->owned; o != nullptr; o = o->next) {
            if (st.installed.count(o->gameId) == 0) continue;
            GameNode* g = findGameById(st.games, o->gameId);
            if (g != nullptr) { std::cout << "   [" << g->gameId << "] " << g->title << "\n"; any = true; }
        }
        if (!any) std::cout << "   (none)\n";
        std::cout << "\n 1. Install a game from my library\n 2. Uninstall a game\n 3. Refresh\n 0. Back\n";
        int c = readInt("Choice: ");
        if (c == -2 || c == 0) return;
        if (c == 3) continue;
        if (c == 1 || c == 2) {
            GameNode* g = askForGame(st);
            if (g == nullptr) continue;
            if (!ownsGame(st.current, g->gameId)) { std::cout << "  You do not own " << g->title << ".\n"; continue; }
            if (c == 1) {
                if (st.installed.count(g->gameId)) { std::cout << "  Already installed.\n"; continue; }
                int sizeMb = 500 + (g->gameId * 937) % 9000;          // a made up size, the same for every run
                std::cout << (st.downloads->enqueue(g->gameId, sizeMb) ? "  Added to the download queue.\n" : "  Already downloading or waiting.\n");
            } else {
                std::cout << (st.installed.erase(g->gameId) ? "  Uninstalled.\n" : "  That game is not installed.\n");
            }
        } else {
            std::cout << "  Invalid choice.\n";
        }
    }
}

//==========================
// Bundle optimizer (knapsack)
//==========================
//--- doBundle -------------------------------------------------------------------------------------
// What    : The Bundle optimizer: chooses the wishlist games with the best total rating for a
//           budget (knapsack) and offers to put them in the cart.
// Used by : runAction (store.h)
//--------------------------------------------------------------------------------------------------
void doBundle(Store& st) {
    tuiSection("BUNDLE OPTIMIZER");
    std::vector<BundleItem> items;
    for (WishNode* w = st.current->wishlist; w != nullptr; w = w->next) {
        GameNode* g = findGameById(st.games, w->gameId);
        if (g == nullptr || ownsGame(st.current, g->gameId)) continue;
        BundleItem item;
        item.gameId = g->gameId;
        item.costCents = g->priceCents;
        item.value = recommendPercent(st.reviews, g->gameId) + 1;       // +1 so unrated games still count
        items.push_back(item);
    }
    if (items.empty()) { std::cout << "  Your wishlist has no game you could buy.\n"; return; }
    std::cout << " Picks the wishlist games with the highest total rating that fit your budget.\n"
              << " Your wallet: " << moneyText(st.current->walletCents) << "\n";
    std::string in;
    if (!readLine("Budget (blank = wallet): ", in)) return;
    int budget = gameTrim(in).empty() ? st.current->walletCents : parseMoney(in);
    if (budget <= 0) { std::cout << "  Nothing to spend.\n"; return; }

    BundleResult r = bestBundle(items, budget);
    if (r.gameIds.empty()) { std::cout << "  No wishlist game fits in " << moneyText(budget) << ".\n"; return; }
    for (size_t i = 0; i < r.gameIds.size(); i++) {
        GameNode* g = findGameById(st.games, r.gameIds[i]);
        if (g != nullptr) std::cout << "  [" << g->gameId << "] " << g->title << "  -  " << priceText(g->priceCents) << "\n";
    }
    std::cout << " Total " << moneyText(r.totalCostCents) << " of " << moneyText(budget) << "\n";
    if (!readLine("Add these games to the cart? (y/n): ", in)) return;
    if (gameToLower(gameTrim(in)) == "y") {
        for (size_t i = 0; i < r.gameIds.size(); i++) if (addToCart(st.cart, r.gameIds[i])) st.undo.record(r.gameIds[i], true);
        std::cout << "  Added.\n";
    }
}

//==========================
// Friend network (graph)
//==========================
//--- doNetwork ------------------------------------------------------------------------------------
// What    : The Friend network screen: size of the friend group (DFS), friends at 1, 2 and 3 steps
//           (BFS), people you may know, and the shortest chain to another user.
// Used by : runAction (store.h)
//--------------------------------------------------------------------------------------------------
void doNetwork(Store& st) {
    tuiSection("FRIEND NETWORK");
    FriendGraph g = buildFriendGraph(st.friends, st.current->userId);
    int me = graphVertexOf(g, st.current->userId);
    std::vector<int> group = graphDfsOrder(g, me);
    std::vector<int> dist = graphBfsDistances(g, me);
    std::cout << " Users in the network: " << g.userIds.size() << "   in your friend group: " << group.size() << "\n";
    for (int level = 1; level <= 3; level++) {
        int n = 0;
        for (size_t v = 0; v < dist.size(); v++) if (dist[v] == level) n++;
        std::cout << "  " << (level == 1 ? "Friends" : level == 2 ? "Friends of friends" : "Three steps away") << ": " << n << "\n";
    }
    std::vector<FriendSuggestion> s = graphSuggestFriends(g, me);
    std::cout << "\n People you may know:\n";
    if (s.empty()) std::cout << "   (no suggestions yet)\n";
    for (size_t i = 0; i < s.size() && i < 5; i++) {
        std::cout << "   " << nameOf(st, s[i].userId) << "  (" << s[i].mutualFriends << " mutual friend" << (s[i].mutualFriends == 1 ? "" : "s") << ")\n";
    }
    std::string in;
    if (!readLine("Username to trace the connection to (blank = back): ", in)) return;
    in = gameTrim(in);
    if (in.empty()) return;
    AccountNode* other = findAccountByName(st.accounts, in);
    if (other == nullptr) { std::cout << "  No such user.\n"; return; }
    std::vector<int> path = graphShortestPath(g, me, graphVertexOf(g, other->userId));
    if (path.empty()) { std::cout << "  There is no chain of friends between you and " << other->username << ".\n"; return; }
    std::cout << "  " << (path.size() - 1) << " step" << (path.size() == 2 ? "" : "s") << ": ";
    for (size_t i = 0; i < path.size(); i++) std::cout << (i ? " -> " : "") << nameOf(st, g.userIds[(size_t)path[i]]);
    std::cout << "\n";
}

//==========================
// Algorithm lab (sorting, searching, timing)
//==========================
//--- doLab ----------------------------------------------------------------------------------------
// What    : The Algorithm lab: compares the six sorts, linear and binary search, and plain and
//           memoized Fibonacci, with time and operation counts.
// Used by : doDiscover
//--------------------------------------------------------------------------------------------------
void doLab(Store& st) {
    (void)st;
    while (true) {
        tuiSection("ALGORITHM LAB");
        std::cout << " 1. Compare the six sorting algorithms\n 2. Linear search vs binary search\n"
                  << " 3. Fibonacci: plain recursion vs memoization\n 0. Back\n";
        int c = readInt("Choice: ");
        if (c == -2 || c == 0) return;
        if (c == 1) {
            int n = readInt("How many numbers (10 to 200000): ");
            if (n < 10 || n > 200000) { if (n != -2) std::cout << "  Out of range.\n"; continue; }
            for (int s = 0; s < SHAPE_COUNT; s++) std::cout << "  " << (s + 1) << ". " << dataShapeName((DataShape)s) << "\n";
            int shape = readInt("Data shape: ");
            if (shape < 1 || shape > (int)SHAPE_COUNT) { if (shape != -2) std::cout << "  Invalid choice.\n"; continue; }
            std::vector<BenchmarkRow> rows = benchmarkAll(n, (DataShape)(shape - 1));
            std::cout << "\n " << n << " numbers, " << dataShapeName((DataShape)(shape - 1)) << "\n";
            std::cout << "  Algorithm        Time(ms)   Compares        Moves  Stable  Average      Worst\n";
            for (size_t i = 0; i < rows.size(); i++) {
                const BenchmarkRow& r = rows[i];
                char line[160];
                if (r.skipped) {
                    std::snprintf(line, sizeof line, "  %-14s   skipped (a quadratic sort would take too long above %d)", sortAlgoName(r.algo), QUADRATIC_SORT_LIMIT);
                } else {
                    std::snprintf(line, sizeof line, "  %-14s %9.3f %10lld %12lld  %-6s  %-10s  %-10s%s",
                                  sortAlgoName(r.algo), r.ms, r.stats.comparisons, r.stats.moves,
                                  sortAlgoIsStable(r.algo) ? "yes" : "no", sortAlgoAverage(r.algo), sortAlgoWorst(r.algo),
                                  r.correct ? "" : "  WRONG RESULT");
                }
                std::cout << line << "\n";
            }
        } else if (c == 2) {
            int n = readInt("Array size (10 to 10000000): ");
            if (n < 10 || n > 10000000) { if (n != -2) std::cout << "  Out of range.\n"; continue; }
            SearchBenchmark b = benchmarkSearch(n);
            std::cout << "  Looking for the LAST item of " << n << " sorted numbers:\n"
                      << "   linear search O(n)     : " << b.linearComparisons << " comparisons\n"
                      << "   binary search O(log n) : " << b.binaryComparisons << " comparisons\n";
        } else if (c == 3) {
            int n = readInt("n (0 to 40): ");
            if (n < 0 || n > 40) { if (n != -2) std::cout << "  Out of range.\n"; continue; }
            long long slowCalls = 0, fastCalls = 0;
            Stopwatch w1;
            long long a = fibonacciNaive(n, &slowCalls);
            double t1 = w1.elapsedMs();
            Stopwatch w2;
            long long b = fibonacciMemo(n, &fastCalls);
            double t2 = w2.elapsedMs();
            std::cout << "  fib(" << n << ") = " << a << (a == b ? "" : "  (MISMATCH)") << "\n"
                      << "   plain recursion : " << slowCalls << " calls, " << t1 << " ms\n"
                      << "   memoization     : " << fastCalls << " calls, " << t2 << " ms\n";
        } else {
            std::cout << "  Invalid choice.\n";
        }
    }
}

//==========================
// Lesson showcase: runs a demo of every lesson, one after another
//==========================
// prints the title of one lesson and waits for the user, true = go on, false = stop
//--- lessonStep -----------------------------------------------------------------------------------
// What    : Shows the title of one lesson of the showcase after the user presses Enter, so the
//           demos can be read one at a time.
// Used by : doShowcase
//--------------------------------------------------------------------------------------------------
bool lessonStep(int number, int total, const std::string& hoa, const std::string& title) {
    std::cout << "\n Press Enter for lesson " << number << " of " << total << ", or 0 to stop.\n";
    int c = readInt("Choice: ");
    if (c == 0 || c == -2) return false;
    tuiSection("HOA " + hoa + " - " + title);
    return true;
}

//--- doShowcase -----------------------------------------------------------------------------------
// What    : The lesson showcase: a short live demo of every lesson (functions, lists, stacks,
//           queues, searching, sorting, trees, graphs, benchmarks, dynamic programming, threads)
//           using the real code of the project. Started from Discover or with the --showcase
//           option.
// Used by : doDiscover, runStore (store.h)
//--------------------------------------------------------------------------------------------------
void doShowcase(Store& st) {
    const int TOTAL = 12;
    int step = 0;
    auto numbers = [](const std::vector<int>& v) {
        std::string out;
        for (size_t i = 0; i < v.size(); i++) out += (i ? ", " : "") + std::to_string(v[i]);
        return out;
    };
    tuiSection("LESSON SHOWCASE");
    std::cout << " Runs a small live demo of every lesson (HOA 1 to 14) with the real code of this project.\n";

    if (!lessonStep(++step, TOTAL, "1, 2.1", "Functions, templates, arrays and pointers")) return;
    {
        int raw[6] = {42, 7, 19, 3, 25, 11};
        SortStats stats;
        std::vector<int> before(raw, raw + 6);
        insertionSort(raw, 6, [](int a, int b) { return a < b; }, &stats);
        std::cout << "  The same template sorts any type. A plain array of 6 ints: " << numbers(before) << "\n"
                  << "  after insertionSort(array, 6, less):                        " << numbers(std::vector<int>(raw, raw + 6)) << "\n"
                  << "  (" << stats.comparisons << " comparisons, " << stats.moves << " moves)\n";
    }

    if (!lessonStep(++step, TOTAL, "3", "Linked lists (single, double, circular)")) return;
    {
        int games = 0;
        for (GameNode* g = st.games.head; g != nullptr; g = g->next) games++;
        RingList<int> ring;
        for (int i = 1; i <= 4; i++) ring.pushBack(i * 10);
        std::cout << "  The catalog is a singly linked list with " << games << " games.\n"
                  << "  A circular doubly linked list of 10, 20, 30, 40 with a cursor:\n  ";
        for (int i = 0; i < 6; i++) { int v = 0; ring.current(v); std::cout << v << (i < 5 ? " -> " : "\n"); ring.moveNext(); }
        std::cout << "  and going back from there: ";
        for (int i = 0; i < 3; i++) { ring.movePrev(); int v = 0; ring.current(v); std::cout << v << (i < 2 ? ", " : "\n"); }
    }

    if (!lessonStep(++step, TOTAL, "4", "Stacks (last in, first out)")) return;
    {
        ArrayStack<std::string> pages;
        pages.push("Store page"); pages.push("Game page"); pages.push("Reviews");
        std::cout << "  Pushed: Store page, Game page, Reviews. Popping gives: ";
        std::string p;
        while (pages.pop(p)) std::cout << p << (pages.empty() ? "\n" : ", ");
        std::cout << "  That is how Back works in the page history.\n";
    }

    if (!lessonStep(++step, TOTAL, "5", "Queues (first in, first out)")) return;
    {
        LinkedQueue<std::string> line;
        line.enqueue("Game A"); line.enqueue("Game B"); line.enqueue("Game C");
        std::cout << "  Download queue, enqueued A, B, C. Served in the order: ";
        std::string g;
        while (line.dequeue(g)) std::cout << g << (line.empty() ? "\n" : ", ");
        CircularQueue<int> recent(3);
        for (int i = 1; i <= 5; i++) recent.enqueueOverwrite(i);
        std::cout << "  Circular queue of size 3 after adding 1..5 keeps: ";
        for (int i = 0, v = 0; recent.at(i, v); i++) std::cout << v << (i < 2 ? ", " : "\n");
    }

    if (!lessonStep(++step, TOTAL, "6", "Searching")) return;
    {
        std::vector<int> data = makeBenchmarkData(1000, SHAPE_SORTED);
        long long linear = 0, binary = 0;
        int key = data[900];
        linearSearch(data.data(), 1000, key, &linear);
        binarySearch(data.data(), 1000, key, [](int a, int b) { return a < b; }, &binary);
        std::cout << "  Looking for " << key << " in 1000 sorted numbers: linear search " << linear
                  << " comparisons, binary search " << binary << ".\n";
        GameNode* first = st.games.head;
        GameNode* found = first ? findGameByTitle(st.games, first->title) : nullptr;
        std::cout << "  The game tree (BST) found the title \"" << (first ? first->title : std::string("-")) << "\": " << (found ? "yes" : "no") << "\n";
    }

    if (!lessonStep(++step, TOTAL, "7, 8", "Sorting the catalog by price with all six algorithms")) return;
    {
        std::vector<const GameNode*> base = collectGames(st.games, std::vector<std::string>());
        auto byPrice = [](const GameNode* a, const GameNode* b) { return a->priceCents < b->priceCents; };
        for (int a = 0; a < ALGO_COUNT; a++) {
            std::vector<const GameNode*> list = base;
            SortStats stats;
            sortWith((SortAlgo)a, list.data(), (int)list.size(), byPrice, &stats);
            std::cout << "  " << fit(sortAlgoName((SortAlgo)a), 15) << " cheapest: "
                      << (list.empty() ? std::string("-") : list.front()->title) << "  (" << stats.comparisons
                      << " comparisons, " << stats.moves << " moves, " << (sortAlgoIsStable((SortAlgo)a) ? "stable" : "not stable") << ")\n";
        }
    }

    if (!lessonStep(++step, TOTAL, "9", "Trees (BST and the genre tree)")) return;
    {
        GenreNode* root = genreBuildDefault();
        std::vector<GenreVisit> pre, post, level;
        genrePreorder(root, 0, pre);
        genrePostorder(root, 0, post);
        genreLevelOrder(root, level);
        auto first = [](const std::vector<GenreVisit>& v) {
            std::string out;
            for (size_t i = 0; i < v.size() && i < 6; i++) out += (i ? ", " : "") + v[i].node->name;
            return out + ", ...";
        };
        std::cout << "  Genre tree: " << genreCount(root) << " nodes, height " << genreHeight(root) << "\n"
                  << "  preorder:    " << first(pre) << "\n  postorder:   " << first(post) << "\n  level order: " << first(level) << "\n";
        genreFree(root);
    }

    if (!lessonStep(++step, TOTAL, "10", "Graphs (friend network, BFS and DFS)")) return;
    {
        FriendGraph g = buildFriendGraph(st.friends, st.current ? st.current->userId : 0);
        size_t edges = 0;
        for (size_t v = 0; v < g.adj.size(); v++) edges += g.adj[v].size();
        std::cout << "  Your friend graph has " << g.userIds.size() << " users and " << edges / 2 << " friendships.\n";
        if (!g.userIds.empty()) {
            std::cout << "  BFS from the first user reaches " << graphDfsOrder(g, 0).size() << " users (DFS finds the same group).\n";
        } else {
            std::cout << "  Add friends (log in, Friends menu) to see the graph grow.\n";
        }
    }

    if (!lessonStep(++step, TOTAL, "11, 14", "Benchmarks (std::chrono)")) return;
    {
        std::vector<BenchmarkRow> rows = benchmarkAll(3000, SHAPE_RANDOM);
        std::cout << "  3000 random numbers:\n";
        for (size_t i = 0; i < rows.size(); i++) {
            char line[120];
            std::snprintf(line, sizeof line, "   %-15s %8.3f ms %10lld comparisons %s", sortAlgoName(rows[i].algo),
                          rows[i].ms, rows[i].stats.comparisons, rows[i].correct ? "" : "WRONG");
            std::cout << line << "\n";
        }
        SearchBenchmark b = benchmarkSearch(1000000);
        std::cout << "  Last item of 1,000,000 numbers: linear " << b.linearComparisons << " comparisons, binary " << b.binaryComparisons << ".\n";
    }

    if (!lessonStep(++step, TOTAL, "12", "Dynamic programming")) return;
    {
        long long slow = 0, fast = 0;
        long long a = fibonacciNaive(25, &slow);
        long long b = fibonacciMemo(25, &fast);
        std::cout << "  fib(25) = " << a << (a == b ? "" : " (MISMATCH)") << ": plain recursion " << slow << " calls, memoized " << fast << " calls.\n";
        std::vector<BundleItem> items = {{1, 1000, 60}, {2, 2000, 100}, {3, 3000, 120}};
        BundleResult r = bestBundle(items, 5000);
        std::cout << "  Knapsack, budget $50 and games $10/60, $20/100, $30/120: value " << r.totalValue << " for " << moneyText(r.totalCostCents) << "\n"
                  << "  Edit distance \"hadse\" to \"hades\": " << editDistance("hadse", "hades") << "\n";
    }

    if (!lessonStep(++step, TOTAL, "13", "Multithreading")) return;
    {
        DownloadManager manager(2);                     // very fast, 2 ms per percent
        manager.enqueue(1, 400);
        manager.enqueue(2, 400);
        std::cout << "  A worker thread installs two games from a queue while this thread watches the progress.\n";
        std::vector<int> done;
        int shown = -1;
        for (int i = 0; i < 400 && done.size() < 2; i++) {
            std::this_thread::sleep_for(std::chrono::milliseconds(5));
            int active = manager.activeId(), pct = manager.activeProgress();
            if (active != 0 && pct / 25 != shown) { shown = pct / 25; std::cout << "   game " << active << " " << progressBar(pct, 100, 20) << " " << pct << "%\n"; }
            std::vector<int> f = manager.takeFinished();
            done.insert(done.end(), f.begin(), f.end());
            if (!f.empty()) shown = -1;
        }
        std::cout << "  Finished in order: " << numbers(done) << ". The chat uses a second thread, see the Messages screen.\n";
    }
    std::cout << "\n All lessons shown.\n";
}

//==========================
// Discover menu, the entry point of everything above
//==========================
//--- doDiscover -----------------------------------------------------------------------------------
// What    : The Discover menu: featured games, genres, recently viewed, page history and the
//           Algorithm lab.
// Used by : runAction (store.h)
//--------------------------------------------------------------------------------------------------
void doDiscover(Store& st) {
    while (true) {
        tuiSection("DISCOVER");
        std::cout << " 1. Featured games (carousel)\n 2. Browse by genre\n 3. Recently viewed\n"
                  << " 4. Page history (back / forward)\n 5. Algorithm lab\n 6. Run all lessons (showcase)\n 0. Back\n";
        int c = readInt("Choice: ");
        if (c == -2 || c == 0) return;
        switch (c) {
            case 1: doFeatured(st); break;
            case 2: doGenres(st); break;
            case 3: doRecent(st); break;
            case 4: doHistory(st); break;
            case 5: doLab(st); break;
            case 6: doShowcase(st); break;
            default: std::cout << "  Invalid choice.\n";
        }
    }
}

#endif //STEAM_SCREENS_H
